SELECT DISTINCT [62304].activity_id AS activity_id_62304, [62304].activity_name AS activity_62304, [62304].purpose, [62304].task_id AS task_id_62304, [62304].task_name AS task_62304, IIf([62304_to_12207_2008].process_id_12207_2008 Is Not Null,[62304_to_12207_2008].process_id_12207_2008,"None") AS process_id_12207_2008, IIf([62304_to_12207_2008].process_id_12207_2008 Is Not Null,[62304_to_12207_2008].process_12207_2008,"None") AS process_12207_2008, IIf([62304_to_12207_2008].process_2_id_12207_2008 Is Not Null,[62304_to_12207_2008].process_2_id_12207_2008,"None") AS process_2_id_12207_2008, IIf([62304_to_12207_2008].process_2_id_12207_2008 Is Not Null,[62304_to_12207_2008].process_2_12207_2008,"None") AS process_2_12207_2008, CInt(Mid([62304].task_id,InStr([62304].task_id,'.')+1,InStr(InStr([62304].task_id,'.')+1,[62304].task_id,'.')-InStr([62304].task_id,'.')-1)) AS id_1, CInt(Mid([62304].task_id,InStr(InStr([62304].task_id,'.')+1,[62304].task_id,'.')+1)) AS id_2, [62304_to_12207_2008].activity_id_12207_2008, [62304_to_12207_2008].task_id_12207_2008
FROM 62304 LEFT JOIN 62304_to_12207_2008 ON ([62304].task_id = [62304_to_12207_2008].task_id_62304) AND ([62304].activity_id = [62304_to_12207_2008].activity_id_62304)
ORDER BY CInt(Mid([62304].task_id,InStr([62304].task_id,'.')+1,InStr(InStr([62304].task_id,'.')+1,[62304].task_id,'.')-InStr([62304].task_id,'.')-1)), CInt(Mid([62304].task_id,InStr(InStr([62304].task_id,'.')+1,[62304].task_id,'.')+1));
